    "verify_code": "import sympy as sp\nx, y = sp.symbols('x y')\n# Helling van BT: 2y + x = 18 -> y = -1/2 x + 9\nm_bt = -1/2\n# Loodregte helling van AC\nm_ac = -1 / m_bt\n# AC gaan deur A(-2, -5)\nc = -5 - m_ac * (-2)\nprint(f\"Helling van AC: {m_ac}\")\nprint(f\"c = {c}\")\nprint(f\"Vergelyking: y = {m_ac}x + {c}\")",
